// AX Phase A sandbox: schema-shape check only — no external fanout
const required = [
  'declaration_id', 'schema_version', 'declared_by', 'start_time',
  'open_ended', 'trigger_condition', 'response_window_used',
  'ratification_status', 'canonical_source', 'sync_state',
  'created_at', 'last_updated_at'
];

const items = $input.all();
const out = [];
for (const item of items) {
  const body = item.json.body || item.json;
  const missing = required.filter(k => !(k in body));
  const isSandbox = String(body.declaration_id || '').startsWith('OA-SANDBOX-');
  out.push({
    json: {
      sandbox: true,
      ok: missing.length === 0 && isSandbox,
      validated_at: new Date().toISOString(),
      declaration_id: body.declaration_id || null,
      missing_fields: missing,
      sandbox_id_check: isSandbox ? 'pass' : 'fail (id must start with OA-SANDBOX-)',
      schema_version: body.schema_version || null,
      received_keys: Object.keys(body).sort(),
      note: 'sandbox dry-run: no Git append, no Slack post, no Telegram post'
    }
  });
}
return out;
